//! HSL color, mirroring `ColorSpace::HSL` from the C++ library.

/// Hue/saturation/lightness color.
///
/// The C++ constructor stores the components as given (no normalization of
/// the hue into `[0, 360)`), so this one does the same.
pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

impl Hsl {
    pub fn new(h: f32, s: f32, l: f32) -> Hsl {
        Hsl { h, s, l }
    }
}

