//! Color conversion helpers, mirroring `ColorSpace::ColorConverter`.

use crate::colorspace::hsl::Hsl;

pub struct ColorConverter;

impl ColorConverter {
    /// Absolute difference between the hues of two HSL colors, folded across
    /// the 180-degree boundary exactly once.
    ///
    /// Matches the observed behavior of the reference binary:
    /// `d = |h1 - h2|`; if `d > 180` the result is `360 - d`, otherwise `d`.
    /// Note the fold is applied only once (not in a loop) and hues are not
    /// normalized, so e.g. hues 720 and 0 yield `-360`.
    pub fn hue_difference(a: &Hsl, b: &Hsl) -> f32 {
        let diff = (a.h - b.h).abs();
        if diff > 180.0 {
            360.0 - diff
        } else {
            diff
        }
    }
}

