//! Reproduces the default `std::cout << float` formatting, i.e. C `printf`
//! `%g` with the default precision of 6 significant digits.

/// Format an `f32` exactly as C++ `std::cout << value` would:
/// `%g` with precision 6 — 6 significant digits, trailing zeros removed,
/// fixed notation for exponents in `[-4, 6)`, scientific otherwise, with a
/// signed, at-least-two-digit exponent (`1e-05`, `-9.99964e+06`).
pub fn format_cxx_float(value: f32) -> String {
    let v = value as f64;
    if v.is_nan() {
        return "nan".to_string();
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf" } else { "inf" }.to_string();
    }
    if v == 0.0 {
        return if v.is_sign_negative() { "-0" } else { "0" }.to_string();
    }

    let negative = v < 0.0;
    let abs = v.abs();

    // Round to 6 significant digits; %g picks the notation from the exponent
    // of the *rounded* value. Rust's `{:.5e}` yields e.g. "9.99964e6".
    let sci = format!("{:.5e}", abs);
    let epos = sci.find('e').expect("scientific notation contains 'e'");
    let exp: i32 = sci[epos + 1..].parse().expect("valid exponent");

    let body = if (-4..6).contains(&exp) {
        // Fixed notation with (6 - 1 - exp) digits after the decimal point.
        let prec = (5 - exp).max(0) as usize;
        strip_trailing_zeros(format!("{:.*}", prec, abs))
    } else {
        // Scientific notation; C++ prints the exponent with a sign and at
        // least two digits.
        let mantissa = strip_trailing_zeros(sci[..epos].to_string());
        format!("{}e{:+03}", mantissa, exp)
    };

    if negative {
        format!("-{}", body)
    } else {
        body
    }
}

/// Remove trailing fractional zeros and a dangling decimal point.
fn strip_trailing_zeros(mut s: String) -> String {
    if s.contains('.') {
        while s.ends_with('0') {
            s.pop();
        }
        if s.ends_with('.') {
            s.pop();
        }
    }
    s
}

